WITH cleaned AS (SELECT *, LEAST(quantity, unit_price) least_quantity_unit_price, ROUND(quantity / unit_price, 2) line_total FROM order_items WHERE product_id IS NOT NULL AND product_id = 9) SELECT CASE WHEN unit_price >= 340 THEN 'HIGH' ELSE 'LOW' END AS unit_price_tier, APPROX_PERCENTILE(unit_price, 0.5) AS unit_price_p50, APPROX_PERCENTILE(least_quantity_unit_price, 0.95) AS least_quantity_unit_price_p95, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT product_id) AS distinct_product_ids, COUNT(*) AS cnt, PERCENTILE_APPROX(least_quantity_unit_price, 0.9) AS least_quantity_unit_price_p90 FROM cleaned GROUP BY 1 ORDER BY unit_price_p50 DESC;
